DO $$
DECLARE b jsonb;v jsonb;w jsonb;s jsonb;single jsonb;rules jsonb:=private.take_two_rules();i integer;choice jsonb;p uuid:=gen_random_uuid();u uuid:=gen_random_uuid();
BEGIN
 b:=private.take_two_board_deal(jsonb_build_object('rules',rules,'score',0,'stage',1),1000);
 PERFORM pg_temp.take_assert(jsonb_array_length(b->'slots')=28 AND b->>'cursor'='29' AND (SELECT count(DISTINCT c)=52 FROM jsonb_array_elements(b->'deck')c),'round one deck, stock and current');
 PERFORM pg_temp.take_assert(NOT(private.take_two_visible(b)?'deck') AND NOT(private.take_two_visible(b)?'cursor'),'private future stock');
 PERFORM pg_temp.take_assert(private.take_two_board_reduce(b,'tick',NULL,3499)=b,'intro has no gameplay clock');
 b:=private.take_two_board_reduce(b,'tick',NULL,3500);
 PERFORM pg_temp.take_assert(b->>'deadline'='103500' AND b->>'phase'='playing','100 seconds begins at intro end');
 PERFORM pg_temp.take_assert(private.take_two_meter(b,4500)=500 AND private.take_two_meter(b,5500)=350 AND private.take_two_meter(b,7500)=50 AND private.take_two_meter(b,90000)=50,'meter hold decay and floor');
 v:=private.take_two_board_reduce(b,'draw',NULL,4500);
 PERFORM pg_temp.take_assert(v->>'score'='0' AND v->'deadline'=b->'deadline' AND v->>'meterAt'='4500' AND v->'slots'=b->'slots' AND v->>'cursor'='30','manual full-board draw floors score, discards old current, unchanged clock and reset speed meter');
 BEGIN PERFORM private.take_two_board_reduce(b,'pair',ARRAY[0,1],4000);RAISE EXCEPTION 'covered pair accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'take_two:illegal_pair' THEN RAISE;END IF;END;
 b:=b||jsonb_build_object('slots',(SELECT jsonb_agg(CASE WHEN slot_i=26 THEN 0 WHEN slot_i=27 THEN 13 ELSE NULL END ORDER BY slot_i) FROM generate_series(0,27)slot_i),'score',1000,'scoreBefore',1000);
 v:=private.take_two_board_reduce(b,'pair',ARRAY[26,27],3500);
 PERFORM pg_temp.take_assert(v->>'score'='40700' AND v#>>'{result,clearBonus}'='10000' AND v#>>'{result,stockBonus}'='23000' AND v#>>'{result,timeBonus}'='5000' AND v->>'cursor'='29','full clear + matching + preserved stock + time');
 b:=b||jsonb_build_object('current',0,'slots',jsonb_set(b->'slots','{26}','null'));
 v:=private.take_two_board_reduce(b,'pair',ARRAY[-1,27],3500);
 PERFORM pg_temp.take_assert(v->>'cursor'='29' AND v->'current'='null'::jsonb AND v#>>'{result,stockBonus}'='23000','final current pair does not refill');
 b:=b||jsonb_build_object('slots',jsonb_set(b->'slots','{27}','1'));
 v:=private.take_two_board_reduce(b,'pair',ARRAY[-1,27],7500);
 PERFORM pg_temp.take_assert(v->>'consecutivePairs'='1' AND v#>>'{result,displayScore}'='1450' AND v#>>'{result,timeBonus}'='4800','Ace two and minimum pair meter');
 b:=b||jsonb_build_object('slots',jsonb_set(b->'slots','{27}','12'));
 PERFORM pg_temp.take_assert(private.take_two_pairs(b)='[[-1,27]]'::jsonb,'King Ace wraps');
 v:=private.take_two_board_reduce(b,'take_score',NULL,4000);
 PERFORM pg_temp.take_assert(v#>>'{result,timeBonus}'='0' AND v#>>'{result,stockBonus}'='0' AND v#>>'{result,clearBonus}'='0','voluntary bank no bonus while stock remains');
 b:=b||'{"cursor":52,"current":5}'::jsonb;
 v:=private.take_two_board_reduce(b,'take_score',NULL,4501);
 PERFORM pg_temp.take_assert(v#>>'{result,timeBonus}'='4900','exhausted dead board whole-second speed bonus');
 v:=private.take_two_board_reduce(b,'pair',ARRAY[-1,27],103500);
 PERFORM pg_temp.take_assert(v#>>'{result,reason}'='timeout' AND v#>>'{result,timeBonus}'='0','exact deadline beats actions');
 b:=private.take_two_board_deal(jsonb_build_object('rules',rules,'score',0,'stage',2),1000);
 PERFORM pg_temp.take_assert(jsonb_array_length(b->'slots')=33 AND b->>'cursor'='34','later rounds layout and stock');
 s:=jsonb_build_object('rules',rules,'score',0,'scores',jsonb_build_object(p::text,0),'players',jsonb_build_array(jsonb_build_object('id',p,'userId',u,'isBot',true)),'turnIndex',0,'stage',1,'stages','[]'::jsonb,'identity',jsonb_build_object('dealerGameId',p,'roundId',p));
 s:=private.take_two_deal(s,1000);single:=s-ARRAY['players','scores','stages','qualified','turnIndex','stage','identity'];
 FOR i IN 0..80 LOOP
  choice:=private.take_two_bot_choice(private.take_two_visible(s),3500+i*100);
  s:=private.take_two_reduce(s,choice->>'action',ARRAY(SELECT value::integer FROM jsonb_array_elements_text(choice->'items')),3500+i*100);
  single:=private.take_two_board_reduce(single,choice->>'action',ARRAY(SELECT value::integer FROM jsonb_array_elements_text(choice->'items')),3500+i*100);
  PERFORM pg_temp.take_assert(s->'slots'=single->'slots' AND s->'score'=single->'score' AND s->'deadline'=single->'deadline','same mode rules and bot visible-only choices');
  EXIT WHEN s->>'phase'='stage_complete';
 END LOOP;
 s:=s||jsonb_build_object('stage',2,'turnIndex',0,'phase','stage_complete','deadline',10000,'scores',jsonb_build_object(p::text,0));
 s:=private.take_two_reduce(s,'tick',NULL,10000);
 PERFORM pg_temp.take_assert(s->>'stage'='3' AND jsonb_array_length(s->'slots')=33,'third normal round at zero score');
 s:=private.take_two_reduce(s,'take_score',NULL,12500);s:=private.take_two_reduce(s,'tick',NULL,(s->>'deadline')::bigint);
 PERFORM pg_temp.take_assert(s->>'phase'='complete','exactly three rounds');
END $$;
SELECT 'Take 2 core rules, timing and mode parity passed' AS proof;
